<template><main class="container page-section narrow"><p class="eyebrow">Notifications</p><h1 class="page-title">通知</h1><div v-if="!items.length" class="empty">暂时没有通知。</div><div v-else class="list"><article v-for="item in items" :key="item.id" class="card notification" :class="{unread:!item.is_read}" @click="read(item)"><b>{{item.actor_name||'系统'}}</b><span>{{text(item.type)}}</span><RouterLink v-if="item.post_slug" :to="`/posts/${item.post_slug}`">{{item.post_title}}</RouterLink><small>{{date(item.created_at)}}</small></article></div></main></template>
<script setup lang="ts">import{onMounted,ref}from'vue';import{RouterLink}from'vue-router';import http from'@/services/http';const items=ref<any[]>([]),text=(type:string)=>({follow:'关注了你',like:'赞了你的文章',comment:'评论了你的文章',reply:'回复了你的评论'}[type]||'有新动态'),date=(v:string)=>new Intl.DateTimeFormat('zh-CN',{dateStyle:'medium'}).format(new Date(v));async function read(item:any){if(!item.is_read){await http.put(`/api/notifications/${item.id}/read`);item.is_read=true}}onMounted(async()=>{try{items.value=(await http.get('/api/notifications')).data.items}catch{}})</script>
<style scoped>.narrow{max-width:760px}.list{display:grid;gap:8px}.notification{padding:15px;display:flex;gap:7px;align-items:center;flex-wrap:wrap}.notification.unread{border-left:3px solid var(--accent)}.notification a{color:var(--accent)}.notification small{color:var(--muted);margin-left:auto}</style>
